      "answer": "<strong>व्यावहारिक सूझबूझ एवं समस्या-समाधान:</strong>\n      <ol>\n        <li><strong>लड़की और छात्रों की समानता:</strong> जिस प्रकार तिब्बती लड़की ने बिना भेड़ों को नुकसान पहुँचाए उनके बाल और सींग बेचकर समस्या का हल निकाला, उसी प्रकार छात्रों ने सीमित साधनों में रसोई के आटे से लेई बनाकर काम पूरा किया। दोनों ने अभाव को बाधा नहीं बनने दिया।</li>\n        <li><strong>व्यावहारिक बुद्धि की महत्ता:</strong> किताबी ज्ञान केवल नियम सिखाता है, परंतु वास्तविक जीवन में अनपेक्षित संकटों से पार पाने के लिए 'आउट-ऑफ-द-बॉक्स' (Out of the box) रचनात्मक सोच और व्यावहारिक युक्ति की आवश्यकता होती है। जो व्यक्ति संसाधनों का बुद्धिमानी से उपयोग करना जानता है, वह कभी पराजित नहीं होता।</li>\n      </ol>",
