      "text": "प्राचीन काल से भारत के सभी फसली पर्व सूर्य के उत्तरायण होने, नई फसलों के पकने और प्रकृति के नए चक्र का सम्मान करने के लिए बनाए गए थे। आधुनिक उपभोक्तावादी संस्कृति में लोग इन त्योहारों के वैज्ञानिक और पर्यावरणीय संदेश को भूलकर केवल औपचारिकता निभाते हैं।",
      "question": "'फसलों के त्योहार' पाठ के आधार पर स्पष्ट कीजिए कि ये पर्व हमें प्रकृति और अन्नदाताओं (किसानों) के प्रति किस प्रकार कृतज्ञ बनना सिखाते हैं?",
      "answer": "<strong>प्रकृति व कृषकों के प्रति कृतज्ञता का दर्शन:</strong>\n      <ol>\n        <li><strong>प्रकृति व सूर्य के प्रति आभार:</strong> सरहुल में वृक्षों की पूजा, पोंगल में सूर्य को नए अन्न का भोग तथा संक्रांति में जल-स्नान यह याद दिलाते हैं कि मानव जीवन सूर्य के ताप, स्वच्छ वायु, उर्वर मिट्टी और जल पर निर्भर है।</li>\n        <li><strong>किसानों के श्रम का सम्मान:</strong> ये सभी त्योहार महीनों तक खेतों में पसीना बहाने वाले कृषकों की मेहनत का उत्सव हैं। नई फसल का पहला दाना ईश्वर और समाज को समर्पित करना अन्न के अपव्यय को रोकने और किसान की गरिमा को पहचानने की सीख देता है।</li>\n      </ol>",
