    "cbq": {
      "title": "साहस, नैतिक कर्तव्य व पारिवारिक प्रेम का संतुलन",
      "text": "बालक के मन में अन्याय और बुराई से लड़ने के लिए श्री राम जैसा वीर बनने की तीव्र इच्छा है, परंतु साथ ही अपनी माँ के प्रति उसका अत्यंत कोमल वात्सल्य और निर्भरता भी प्रकट होती है।",
      "question": "यह कविता बाल-मनोविज्ञान के किन दो परस्पर विरोधी भावों (वीरता व मातृ-स्नेह) का सुंदर समन्वय प्रस्तुत करती है? स्पष्ट कीजिए।",
      "answer": "<strong>वीरता व वात्सल्य का अनूठा समन्वय:</strong>\n      <ol>\n        <li><strong>कर्तव्य व अन्याय के विरुद्ध संकल्प (वीर रस):</strong> बालक साधारण विलासिता के खिलौनों के बजाय तीर-कमान चुनता है, जो दर्शाता है कि बच्चों में स्वाभाविक रूप से वीरों जैसा बनने और समाज से बुराई मिटाने की प्रेरक उमंग होती है।</li>\n        <li><strong>मातृ-प्रेम व सुरक्षा का भाव (वात्सल्य रस):</strong> वीरता के संकल्प के साथ ही बालक माँ के आँचल की गर्माहट को नहीं छोड़ना चाहता। वह समझता है कि माँ के स्नेह के बिना संसार का कोई भी पद या विजय अधूरी है। यह संतुलन बच्चे को कठोर बनने से रोककर दयालु बनाता है।</li>\n      </ol>",
      "rubric": "1.5 अंक वीरता व तीर-कमान के भाव के लिए + 3.5 अंक मातृ-स्नेह व भावनात्मक संतुलन के विवेचन हेतु = 5 अंक"
    }
