      "title": "श्रम की गरिमा व कला का सम्मान",
      "text": "शहंशाह अकबर ने पूरे हिंदुस्तान का सम्राट होने के बावजूद एक दस वर्ष के गरीब मजदूर बालक केशव के हुनर को झुककर प्रणाम किया और उसके पास जमीन पर बैठकर स्वयं सीखने का प्रयास किया।",
      "question": "यह घटना सम्राट अकबर के किस महान मानवीय गुण को दर्शाती है और आज के समाज को श्रम व हस्तशिल्पियों के प्रति क्या संदेश देती है?",
      "answer": "<strong>कला की सर्वोच्चता एवं श्रम का सम्मान:</strong>\n      <ol>\n        <li><strong>अकबर की विनम्रता:</strong> यह घटना सिद्ध करती है कि सच्चा महान व्यक्ति सत्ता और पद के अहंकार में नहीं जीता। अकबर ने समझा कि कला और हुनर के सामने राजा और रंक का कोई भेद नहीं होता; कलाकार अपने क्षेत्र का सच्चा स्वामी होता है।</li>\n        <li><strong>समाज के लिए संदेश:</strong> आज भी शारीरिक श्रम करने वाले मूर्तिकारों, बढ़इयों, बुनकरों और राजमिस्त्रियों को हेय दृष्टि से नहीं देखा जाना चाहिए। उनके हाथों में देश की संस्कृति और शिल्पकला की अमूल्य धरोहर सुरक्षित है; उन्हें यथोचित सम्मान और प्रोत्साहन मिलना चाहिए।</li>\n      </ol>",
