    "cbq": {
      "title": "समावेशी समाज व दिव्यांगों का सशक्तिकरण",
      "text": "यदि इला को दसवीं की बोर्ड परीक्षा में अतिरिक्त समय या एक लेखक (Scribe) मिलने की जानकारी होती, तो वह परीक्षा में अनुत्तीर्ण न होती। आज भी कई दिव्यांग बच्चे जागरूक न होने के कारण अपनी शिक्षा बीच में छोड़ देते हैं।",
      "question": "इला सचानी के जीवन के संदर्भ में बताइए कि हमारे विद्यालयों को दिव्यांग बच्चों के लिए अधिक सुलभ और समावेशी (Inclusive) बनाने के लिए क्या कदम उठाने चाहिए?",
      "answer": "<strong>दिव्यांगों हेतु समावेशी विद्यालयी व्यवस्था:</strong>\n      <ol>\n        <li><strong>परीक्षाओं में विशेष सुविधा व राइटर का प्रावधान:</strong> दिव्यांग छात्रों को परीक्षा में अतिरिक्त समय, प्रश्न-पत्र पढ़ने हेतु सहायक या राइटर तथा कंप्यूटर आधारित मूल्यांकन की पूर्ण सुविधा व पूर्व जानकारी दी जानी चाहिए।</li>\n        <li><strong>सहानुभूति नहीं, अवसर व प्रोत्साहन:</strong> समाज को दिव्यांगों पर तरस खाने के बजाय उनकी विशिष्ट प्रतिभा (जैसे- इला की चित्रकला व कशीदाकारी) को पहचानकर व्यावसायिक प्रशिक्षण और उचित मंच प्रदान करना चाहिए।</li>\n      </ol>",
      "rubric": "1.5 अंक परीक्षा सुविधाओं के उल्लेख हेतु + 3.5 अंक समावेशी वातावरण व कौशल प्रोत्साहन के विश्लेषण के लिए = 5 अंक"
    }
