        "category": "साक्षात्कार से • प्रश्नोत्तर",
        "q": "पहाड़ी क्षेत्रों (जैसे किन्नौर और लाहौल-स्पीति) में डाकियों को किन-किन भीषण कठिनाइयों का सामना करना पड़ता है?",
        "marks": 3,
        "ans": "पहाड़ी क्षेत्रों में डाकियों को प्रतिदिन 25-26 किलोमीटर ऊँचे-नीचे बर्फीले पहाड़ों पर पैदल चलना पड़ता है। सर्दियों में तापमान शून्य से बहुत नीचे चला जाता है, जिससे पैर बर्फ में धँसने पर 'गैंग्रीन' (पैर सुन्न होकर गल जाना) का खतरा रहता है। बर्फ पर सूर्य की तेज़ किरणों के परावर्तन से आँखों की रोशनी जाने (स्नो-ब्लाइंडनेस) और भूस्खलन की निरंतर आशंका रहती है।",
