        "q": "कंवरसिंह को 'बेस्ट पोस्टमैन अवार्ड' क्यों और किस वीरतापूर्ण कार्य के लिए दिया गया?",
        "marks": 3,
        "ans": "शिमला के जनरल पोस्ट ऑफिस में रात की ड्यूटी के दौरान कुछ हथियारबंद लुटेरे सरकारी तिजोरी लूटने घुस आए। कंवरसिंह ने निडरता से उनका मुकाबला किया और जान की बाज़ी लगाकर सरकारी खजाने को लुटने से बचा लिया। लुटेरों के रॉड के प्रहार से उनके सिर में गंभीर चोटें आईं और उनकी एक आँख की रोशनी चली गई। उनकी इस अद्वितीय कर्तव्यनिष्ठा व वीरता के लिए भारत सरकार ने उन्हें 'बेस्ट पोस्टमैन अवार्ड' से सम्मानित किया।",
