      "answer": "<strong>कर्तव्यनिष्ठा और सेवा-भाव:</strong>\n      <ol>\n        <li><strong>काम की प्रतिष्ठा धन से नहीं, सेवा से है:</strong> कंवरसिंह का जीवन सिखाता है कि किसी भी काम की महत्ता केवल वेतन से नहीं, बल्कि इस बात से तय होती है कि हम कितने लोगों के जीवन में खुशियाँ ला रहे हैं।</li>\n        <li><strong>विपरीत परिस्थितियों में निष्ठा:</strong> परिस्थितियाँ चाहे जितनी कठिन हों, अपने दायित्व से पीछे न हटना और सत्य व संस्था के प्रति वफादार रहना ही एक सच्चे नागरिक का सबसे बड़ा भूषण है।</li>\n      </ol>",
