        "q": "कुम्मी और रोहित की पढ़ाई आज की हमारी पढ़ाई से किस प्रकार भिन्न थी?",
        "marks": 3,
        "ans": "कुम्मी और रोहित (वर्ष 2155) किसी स्कूल की इमारत में नहीं जाते थे और न ही उन्हें कोई मनुष्य पढ़ाता था। उनके घर के एक विशेष कमरे में एक बड़ी स्क्रीन वाला यांत्रिक कंप्यूटर (रोबोटिक टीचर) लगा था। वे मशीन के खांचे (Slot) में पंच कोड वाले होमवर्क डालते थे, और मशीन तुरंत परिणाम सुना देती थी। उनके पास कागज़ की छपी हुई किताबें नहीं थीं, बल्कि स्क्रीन पर शब्द चला करते थे।",
