        "marks": 3,
        "ans": "कुम्मी सोच रही थी कि पुराने ज़माने के स्कूलों में कितना आनंद आता होगा! एक ही उम्र के सारे बच्चे हँसते-खेलते, बातें करते एक साथ स्कूल जाते थे। उन्हें पढ़ाने वाले इंसान होते थे जो बच्चों की भावनाओं को समझते थे। सब बच्चे एक जैसा पाठ पढ़ते थे और एक-दूसरे के होमवर्क में मदद कर सकते थे। वह एकाकी यांत्रिक कमरे की तुलना में पुराने स्कूलों के उल्लास को याद कर भावुक हो गई।",
