        "q": "अंधेर नगरी की क्या विचित्रता थी और गुरु जी ने वहाँ रुकने से मना क्यों किया?",
        "marks": 3,
        "ans": "अंधेर नगरी की विचित्रता यह थी कि वहाँ सभी वस्तुएं—चाहे वह साधारण सब्ज़ी (भाजी) हो या कीमती मिठाई (खाजा, रबड़ी-मलाई)—एक ही भाव यानी 'टके सेर' (एक टके में एक सेर) बिकती थीं। गुरु जी दूरदर्शी थे; वे समझ गए कि जहाँ भले-बुरे, मूर्ख-विद्वान और गुण-अवगुण का कोई विवेक नहीं होता, ऐसे मूर्ख राजा के राज्य में कभी भी प्राणों पर संकट आ सकता है।",
