        "q": "गुरु जी ने अपने चेले के प्राण बचाने के लिए क्या चाल चली?",
        "marks": 3,
        "ans": "जब चेले को फाँसी के तख्ते पर ले जाया जा रहा था, तो गुरु जी ने ऐन वक्त पर पहुँचकर चेले से पहले फाँसी पर चढ़ने का तीव्र विवाद शुरू कर दिया। जब राजा ने कारण पूछा, तो गुरु जी ने रहस्यमयी वाणी में कहा—'यह ऐसा दिव्य और शुभ मुहूर्त है कि इस समय जो भी फाँसी पर चढ़ेगा, वह अगले जन्म में चक्रवर्ती सम्राट बनेगा।' मूर्ख राजा लोभ में आ गया और उसने कहा कि राजा केवल मैं ही बनूँगा; वह स्वयं फाँसी के फंदे पर लटक गया और चेले के प्राण बच गए।",
