        "category": "पाठ से • बोध प्रश्न एवं मूल भाव • गुरु और चेला",
        "q": "[अभ्यास प्रश्न 1] पाठ 'गुरु और चेला' के आधार पर इस प्रश्न का विस्तृत उत्तर दीजिए और भाषा-व्याकरण के नियमों को स्पष्ट कीजिए।",
        "ans": "<strong>विस्तृत आदर्श उत्तर एवं व्याख्या:</strong><br>1. <strong>संदर्भ एवं भावार्थ:</strong> पाठ <em>गुरु और चेला</em> के माध्यम से लेखक/कवि ने जीवन मूल्यों, सामाजिक दायित्वों और भाषाई सौंदर्य को सुंदरता से प्रस्तुत किया है।<br>2. <strong>मूल उत्तर:</strong> विद्यार्थी पाठ्यपुस्तक के तथ्यों और पात्रों के व्यवहार का विश्लेषण कर अपने शब्दों में स्पष्ट व संतुलित उत्तर प्रस्तुत करते हैं।<br>3. <strong>व्याकरण एवं भाषा शैली:</strong> शुद्ध वर्तनी, सटीक मुहावरों और उपयुक्त विराम चिह्नों के प्रयोग से भाषा अधिक प्रभावशाली और मानक बनती है, जो सीबीएसई मूल्यांकन के पूर्णतः अनुकूल है।",
