      "text": "चेला सस्ते भोजन के लालच में गुरु की हितकारी चेतावनी भूल गया, जिसके कारण वह मृत्यु के मुँह तक पहुँच गया था।",
      "question": "'गुरु और चेला' कविता से हमें गुरु के मार्गदर्शन और बिना सोचे-समझे मिलने वाले सस्ते आकर्षणों के बारे में क्या सीख मिलती है?",
      "answer": "<strong>विवेक और सत्संग की महत्ता:</strong>\n      <ol>\n        <li><strong>लोभ पतन का कारण है:</strong> चेला सस्ते खाने के मोह में फँसकर अपनी जान जोखिम में डाल बैठा। जीवन में जो चीज़ बिना मेहनत या अस्वाभाविक रूप से सस्ती मिले, उसके पीछे छिपे खतरे को पहचानना चाहिए।</li>\n        <li><strong>बड़ों और गुरु की सीख:</strong> अनुभवी गुरु की सलाह को अनदेखा करना विनाशकारी होता है; गुरु की बुद्धिमत्ता ने ही अंततः असंभव को संभव कर चेले की रक्षा की।</li>\n      </ol>",
