    "cbq": {
      "title": "दादा-दादी व पोते-पोती के बीच पीढ़ीगत संवाद",
      "text": "आजकल एकल परिवारों (Nuclear Families) के बढ़ने से बच्चे अपने दादा-दादी के स्नेह, लोरियों और जीवन-अनुभवों से दूर होते जा रहे हैं।",
      "question": "'स्वामी की दादी' पाठ के आधार पर समझाइए कि संयुक्त परिवारों में बुजुर्गों का सान्निध्य बच्चों के मानसिक व भावनात्मक विकास के लिए क्यों आवश्यक है?",
      "answer": "<strong>बुजुर्गों का सान्निध्य एवं बाल-विकास:</strong>\n      <ol>\n        <li><strong>भावनात्मक सुरक्षा कवच:</strong> बच्चे अपने माता-पिता की डांट के बाद अक्सर दादा-दादी के पास शरण लेते हैं। बुजुर्ग बच्चों को बिना शर्त प्यार (Unconditional Love) और धैर्यपूर्वक सुनने का समय देते हैं, जिससे बच्चों का तनाव दूर होता है।</li>\n        <li><strong>संस्कृति व नैतिक मूल्यों का हस्तांतरण:</strong> दादी की कहानियों के माध्यम से बच्चों में अनजाने ही सत्यवादिता, परोपकार और पारिवारिक जड़ों के प्रति सम्मान के बीज अंकुरित होते हैं।</li>\n      </ol>",
      "rubric": "1.5 अंक भावनात्मक सुरक्षा के लिए + 3.5 अंक सांस्कृतिक व नैतिक मूल्यों के हस्तांतरण के विवेचन हेतु = 5 अंक"
    }
